param([int[]]$Scenarios=@(1),[int]$BasePort=0,[int]$Port=0)
$ErrorActionPreference='Stop'
$repo=Split-Path $PSScriptRoot
$mvn="$env:USERPROFILE\.m2\wrapper\dists\apache-maven-3.9.12-bin\5nmfsn99br87k5d4ajlekdq10k\apache-maven-3.9.12\bin\mvn.cmd"
$ff=(Get-ChildItem "$env:TEMP\transcoder-ffmpeg-portable-qa" -Recurse -Filter ffmpeg.exe|Select-Object -First 1).FullName
$fp=(Get-ChildItem "$env:TEMP\transcoder-ffmpeg-portable-qa" -Recurse -Filter ffprobe.exe|Select-Object -First 1).FullName
$video=Join-Path $env:TEMP 'youtube-unit-qa-videos\v480.mp4';$root=Join-Path $env:TEMP 'youtube-unit-concurrency-final4';New-Item -ItemType Directory -Force $root|Out-Null
foreach($n in $Scenarios){$port=if($BasePort){$BasePort+$n}else{Get-Random -Minimum 20000 -Maximum 40000};$dir=Join-Path $root "clients-$n";New-Item -ItemType Directory -Force $dir|Out-Null;$summary=[ordered]@{clients=$n;port=$port;stage='startup';result='FAIL';healthAttempts=@();jobsAttempts=@();http202=0;http429=0;completed=0;failed=0;downloadValid=$false;reason=$null};$api=$null;try{$data=Join-Path $dir data;New-Item -ItemType Directory -Force $data|Out-Null;$env:PORT="$port";$env:TRANSCODER_DATA_DIR=$data;$env:FFMPEG_BIN=$ff;$env:FFPROBE_BIN=$fp;$api=Start-Process $mvn -ArgumentList 'exec:java' -WorkingDirectory $repo -RedirectStandardOutput (Join-Path $dir api.log) -RedirectStandardError (Join-Path $dir api.err) -PassThru;$ready=$false;for($i=0;$i-lt 180;$i++){try{$sw=[Diagnostics.Stopwatch]::StartNew();$h=Invoke-WebRequest -UseBasicParsing "http://127.0.0.1:$port/health" -TimeoutSec 3;$sw.Stop();$summary.healthAttempts+=[pscustomobject]@{status=$h.StatusCode;body=$h.Content;ms=$sw.ElapsedMilliseconds}}catch{$summary.healthAttempts+=[pscustomobject]@{status=0;body='';error=$_.Exception.Message}};try{$sw=[Diagnostics.Stopwatch]::StartNew();$j=Invoke-WebRequest -UseBasicParsing "http://127.0.0.1:$port/jobs" -TimeoutSec 3;$sw.Stop();$summary.jobsAttempts+=[pscustomobject]@{status=$j.StatusCode;body=$j.Content;ms=$sw.ElapsedMilliseconds};$empty=([string]$j.Content).Trim() -eq '[]'}catch{$summary.jobsAttempts+=[pscustomobject]@{status=0;body='';error=$_.Exception.Message};$empty=$false};if($h.StatusCode -eq 200 -and $empty){$ready=$true;break};Start-Sleep -Milliseconds 500};if(!$ready){throw 'startup timeout';}$summary.stage='upload';$raw=& curl.exe -sS -w "`nHTTP:%{http_code}" -X POST -F "file=@$video;type=video/mp4" -F 'origin=cliente-1' -F 'permission=sintetico' -F 'profiles=360p' "http://127.0.0.1:$port/videos" 2>&1;$text=$raw -join "`n";Set-Content (Join-Path $dir upload.txt) $text;if($text -notmatch 'HTTP:202'){throw "upload HTTP não 202: $text"};$summary.http202=1;$m=[regex]::Match($text,'"id":"([^"]+)"');if(!$m.Success){throw 'ID ausente'};$id=$m.Groups[1].Value;$summary.stage='poll';$job=$null;for($i=0;$i-lt 120;$i++){$job=Invoke-RestMethod "http://127.0.0.1:$port/jobs/$id";if($job.status -in @('COMPLETED','FAILED')){break};Start-Sleep -Milliseconds 500};if($job.status -ne 'COMPLETED'){throw "job final=$($job.status)"};$summary.completed=1;$summary.stage='download';$full=Invoke-RestMethod "http://127.0.0.1:$port/jobs/$id";$out=$full.outputs|Select-Object -First 1;$dst=Join-Path $dir result.mp4;Invoke-WebRequest -UseBasicParsing "http://127.0.0.1:$port/arquivos/$($out.id)" -OutFile $dst;$probe=& $fp -v error -show_entries format=duration:stream=codec_name,width,height -of json $dst;Set-Content (Join-Path $dir ffprobe.json) ($probe -join "`n");if($LASTEXITCODE -ne 0){throw 'ffprobe falhou'};$summary.downloadValid=$true;$summary.stage='completed';$summary.result='PASS'}catch{$summary.reason=$_.Exception.Message}finally{$summary|ConvertTo-Json -Depth 8|Set-Content (Join-Path $dir summary.json);if($api -and !$api.HasExited){& taskkill.exe /PID $api.Id /T /F 2>$null|Out-Null}};if($summary.result -ne 'PASS'){exit 1}}
